head.b:skin:
:root {
  --c-primary: #0b2d5e;
  --c-accent: #d22232;
  --c-text: #1f2328;
  --c-muted: #586171;
  --c-line: #e5e9ef;
}
*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; text-size-adjust: 100%; }
body {
  margin: 0;
  min-width: 320px;
  color: var(--c-text);
  background: #fff;
  font: 16px/1.6 system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
}
a { color: var(--c-primary); text-decoration: none; overflow-wrap: anywhere; }
a:hover, a:focus-visible { color: var(--c-accent); }
img { display: block; max-width: 100%; height: auto; }
.lkk-wrap { width: calc(100% - 24px); max-width: 1100px; margin-inline: auto; }
.lkk-top { min-height: 32px; background: var(--c-primary); color: #fff; font-size: 13px; }
.lkk-top .lkk-wrap { display: flex; gap: 16px; align-items: center; min-height: 32px; }
.lkk-top a { color: #fff; }
.lkk-head { display: flex; align-items: center; justify-content: space-between; gap: 16px; min-height: 76px; }
.lkk-site-title { margin: 0; font-size: 28px; line-height: 1; font-weight: 800; letter-spacing: -.04em; }
.lkk-logo { display: flex; flex: 0 0 auto; align-items: center; gap: 12px; }
.lkk-logo img { width: 64px; height: 64px; object-fit: contain; }
.lkk-brand-name { display: block; color: var(--c-primary); }
.lkk-search { display: flex; gap: 6px; }
.lkk-search input { width: min(230px, 42vw); min-height: 40px; padding: 8px; border: 1px solid var(--c-line); }
.lkk-search button { min-height: 40px; padding: 8px 14px; border: 0; color: #fff; background: var(--c-primary); }
.lkk-nav { border-block: 1px solid var(--c-line); }
.lkk-nav .lkk-wrap { display: flex; gap: 16px; overflow-x: auto; white-space: nowrap; }
.lkk-nav a { display: block; padding: 10px 0; font-size: 14px; font-weight: 700; }
.lkk-main { width: calc(100% - 24px); max-width: 1100px; min-height: 40vh; margin: 0 auto; padding-block: 18px 32px; }
.lkk-headline { display: grid; grid-template-columns: minmax(0, 1fr) 320px; align-items: center; gap: 20px; min-height: 190px; padding: 16px 0 20px; border-bottom: 1px solid var(--c-line); }
.lkk-headline-media { grid-column: 2; grid-row: 1; }
.lkk-headline-image, .lkk-headline-image-empty { display: grid; width: 100%; aspect-ratio: 16 / 9; place-items: center; object-fit: cover; background: #f3f5f7; }
.lkk-headline-image-empty { color: var(--c-muted); font-weight: 700; }
.lkk-headline-copy { grid-column: 1; grid-row: 1; min-width: 0; }
.lkk-headline h2 { margin: 0; font-size: clamp(24px, 3.5vw, 36px); line-height: 1.18; letter-spacing: -.025em; }
.lkk-headline p { max-width: 760px; margin: 10px 0 0; color: var(--c-muted); }
.lkk-list { display: grid; gap: 0; }
.lkk-archive-grid { display: grid; gap: 0; }
.lkk-item { display: grid; grid-template-columns: 96px minmax(0, 1fr); gap: 12px; min-height: 88px; padding: 12px 0; border-bottom: 1px solid var(--c-line); }
.lkk-thumb { width: 96px; height: 64px; object-fit: cover; background: #f3f5f7; }
.lkk-label, .lkk-meta { color: var(--c-muted); font-size: 12px; }
.lkk-item h2, .lkk-item h3 { margin: 2px 0; font-size: 16px; line-height: 1.35; }
.lkk-more { display: inline-block; margin-top: 16px; padding: 8px 12px; border: 1px solid var(--c-line); }
.lkk-archive-head { margin: 0 0 16px; padding-bottom: 12px; border-bottom: 1px solid var(--c-line); }
.lkk-archive-head h1 { margin: 0; font-size: 28px; line-height: 1.25; }
.lkk-article-shell { min-width: 0; max-width: 760px; margin: 0 auto; }
.lkk-article-header { margin-bottom: 14px; }
.lkk-article-title { margin: 12px 0; font-size: clamp(28px, 5vw, 42px); line-height: 1.2; }
.lkk-article-title { color: var(--c-text); }
.lkk-breadcrumb { display: flex; flex-wrap: wrap; gap: 6px; margin: 0 0 12px; color: var(--c-muted); font-size: 13px; }
.lkk-article-byline { display: flex; flex-wrap: wrap; gap: 6px 14px; color: var(--c-muted); font-size: 13px; }
.lkk-article-featured { margin: 18px 0; }
.lkk-article-featured-image { width: 100%; height: auto; aspect-ratio: 1200 / 630; object-fit: cover; }
.lkk-article-body { font-size: 16px; line-height: 1.7; overflow-wrap: anywhere; }
@media (min-width: 700px) {
  .lkk-wrap, .lkk-main { width: calc(100% - 32px); }
  .lkk-head { min-height: 88px; }
  .lkk-list, .lkk-archive-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: 24px; }
}
@media (min-width: 800px) and (max-width: 1199px) {
  .berita-utama:has(#Blog1 .lkk-article) { display: grid; width: calc(100% - 20px); max-width: 1100px; margin-inline: auto; grid-template-columns: minmax(0, 1fr) 284px; align-items: start; column-gap: 26px; }
  .berita-utama:has(#Blog1 .lkk-article) > #Blog1, .berita-utama:has(#Blog1 .lkk-article) > #PopularPosts1 { min-width: 0; }
}
@media (min-width: 1200px) {
  .berita-utama:has(#Blog1 .lkk-article) { display: grid; width: calc(100% - 32px); max-width: 1100px; margin-inline: auto; grid-template-columns: minmax(0, 1fr) 320px; align-items: start; column-gap: 16px; }
  .berita-utama:has(#Blog1 .lkk-article) > #Blog1, .berita-utama:has(#Blog1 .lkk-article) > #PopularPosts1 { min-width: 0; }
}
@media (max-width: 699px) {
  .lkk-head { min-height: 0; flex-wrap: wrap; gap: 8px; padding-block: 8px; }
  .lkk-site-title, .lkk-search { width: 100%; }
  .lkk-site-title { font-size: 22px; }
  .lkk-logo img { width: 52px; height: 52px; }
  .lkk-search input { width: auto; flex: 1; }
  .lkk-headline { grid-template-columns: 112px minmax(0, 1fr); gap: 12px; min-height: 0; padding: 12px 0; }
  .lkk-headline-media { grid-column: 1; }
  .lkk-headline-copy { grid-column: 2; }
  .lkk-headline h2 { font-size: 21px; }
}

body.script:
//
(function () {
  'use strict';

  var article = document.querySelector('.lkk-article .lkk-article-body');
  var featured = document.querySelector('.lkk-article-featured-image');
  var articleHeading = document.querySelector('.lkk-article-title');
  var toc = document.querySelector('.lkk-article-toc');
  var list = toc && toc.querySelector('ol');

  if (article && featured) {
    var featuredFigure = featured.closest('figure');
    var articleTitle = articleHeading && articleHeading.textContent.trim();

    function imageKey(source) {
      var url = new URL(source, document.baseURI);
      var parts = url.pathname.split('/');
      var normalized = [];

      for (var i = 0; i < parts.length; i += 1) {
        if (parts[i] && !/^(?:s\d+(?:-.+)?|w\d+(?:-h\d+)?(?:-.+)?)$/.test(parts[i])) {
          normalized.push(parts[i]);
        }
      }

      return url.origin + '/' + normalized.join('/');
    }

    var featuredKey = imageKey(featured.currentSrc || featured.src);
    var image = article.querySelector('img');

    if (image) {
      var isFeaturedDuplicate = imageKey(image.currentSrc || image.src) === featuredKey;
      var wrapper = image.closest('figure, table.tr-caption-container');
      var link = image.closest('a');
      var caption = wrapper && wrapper.querySelector('figcaption, .tr-caption');

      if (isFeaturedDuplicate) {
        if (!featured.getAttribute('alt') && image.getAttribute('alt')) {
          featured.alt = image.getAttribute('alt');
        }
        if (!featured.getAttribute('title') && image.getAttribute('title')) {
          featured.title = image.getAttribute('title');
        }
        if (caption && caption.textContent.trim() && featuredFigure &&
            !featuredFigure.querySelector('figcaption')) {
          var featuredCaption = document.createElement('figcaption');
          Array.prototype.forEach.call(caption.childNodes, function (node) {
            featuredCaption.appendChild(node.cloneNode(true));
          });
          while (featuredCaption.lastChild &&
              (featuredCaption.lastChild.nodeName === 'BR' ||
               (featuredCaption.lastChild.nodeType === 3 && !featuredCaption.lastChild.nodeValue.trim()))) {
            featuredCaption.removeChild(featuredCaption.lastChild);
          }
          featuredFigure.appendChild(featuredCaption);
        }
      }

      if (link && link.querySelectorAll('img').length === 1 && !link.textContent.trim()) {
        link.remove();
      } else {
        image.remove();
      }

      if (wrapper && !wrapper.querySelector('img')) {
        wrapper.remove();
      }
    }

    if (!featured.getAttribute('alt')) {
      featured.alt = articleTitle || 'Foto artikel';
    }
    if (!featured.getAttribute('title')) {
      featured.title = articleTitle
        ? articleTitle + ' | Liputan Kabar Kota'
        : 'Liputan Kabar Kota';
    }
  }

  if (!article || !toc || !list) return;

  var headings = article.querySelectorAll('h2, h3');
  var usedIds = Object.create(null);

  headings.forEach(function (heading, index) {
    var title = heading.textContent.replace(/\s+/g, ' ').trim();
    if (!title) return;

    var base = heading.id || title.toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-|-$/g, '') || 'bagian-' + (index + 1);
    var id = base;
    var suffix = 2;

    while (usedIds[id] || (document.getElementById(id) && document.getElementById(id) !== heading)) {
      id = base + '-' + suffix;
      suffix += 1;
    }

    usedIds[id] = true;
    heading.id = id;

    var item = document.createElement('li');
    var link = document.createElement('a');
    link.href = '#' + id;
    link.textContent = title;
    item.appendChild(link);
    list.appendChild(item);
  });

  if (list.children.length >= 3) {
    toc.hidden = false;
  } else {
    list.textContent = '';
  }
}());
//
